def ttf_to_pf2(ttf_path, pt_size, out_path, font_name="CyberFont"):
    font = ImageFont.truetype(ttf_path, pt_size)
    ascent, descent = font.getmetrics()
    
    glyphs_raw = []
    max_w = 0
    max_h = 0
    
    chars = [chr(c) for c in range(32, 127)] + ["✦", "▶", "■", "▲", "◆", "●", "★", "⚡", "⚙", "⏻", "↺", "←", "→", "↑", "↓", "░", "▒", "▓", "█"]
    
    for ch in chars:
        cp = ord(ch)
        try:
            mask = font.getmask(ch, mode="1")
            bbox = font.getbbox(ch)
        except Exception:
            continue
            
        if bbox is None or mask.size[0] == 0 or mask.size[1] == 0:
            if ch == " ":
                dwidth = int(font.getlength(" ")) if hasattr(font, "getlength") else pt_size // 3
                gbytes = struct.pack(">HHhhh", 0, 0, 0, 0, dwidth)
                glyphs_raw.append((cp, gbytes))
            continue
            
        w, h = mask.size
        left, top, right, bottom = bbox
        xoff = left
        yoff = ascent - bottom
        dwidth = int(font.getlength(ch)) if hasattr(font, "getlength") else w + 1
        
        max_w = max(max_w, w)
        max_h = max(max_h, h)
        
        raw_bits = []
        for y in range(h):
            for x in range(w):
                raw_bits.append(1 if mask.getpixel((x, y)) > 0 else 0)
        
        bmp = bytearray()
        cur_b = 0
        b_idx = 0
        for b in raw_bits:
            if b:
                cur_b |= (1 << (7 - b_idx))
            b_idx += 1
            if b_idx == 8:
                bmp.append(cur_b)
                cur_b = 0
                b_idx = 0
        if b_idx > 0:
            bmp.append(cur_b)
            
        gbytes = struct.pack(">HHhhh", w, h, xoff, yoff, dwidth) + bmp
        glyphs_raw.append((cp, gbytes))
        
    glyphs_raw.sort(key=lambda x: x[0])
    
    header = bytearray(b"FILE\x00\x00\x00\x04PFF2")
    nbytes = font_name.encode("utf-8")
    header.extend(b"NAME" + struct.pack(">I", len(nbytes)) + nbytes)
    header.extend(b"PTSZ\x00\x00\x00\x02" + struct.pack(">H", pt_size))
    header.extend(b"WEIG\x00\x00\x00\x02" + struct.pack(">H", 700))
    header.extend(b"MAXW\x00\x00\x00\x02" + struct.pack(">H", max_w))
    header.extend(b"MAXH\x00\x00\x00\x02" + struct.pack(">H", max_h))
    header.extend(b"ASCE\x00\x00\x00\x02" + struct.pack(">h", ascent))
    header.extend(b"DESC\x00\x00\x00\x02" + struct.pack(">h", descent))
    
    num_chars = len(glyphs_raw)
    chix_len = num_chars * 9
    
    data_header_pos = len(header) + 8 + chix_len
    data_payload_pos = data_header_pos + 8
    
    chix_bytes = bytearray()
    cur_offset = data_payload_pos
    glyphs_body = bytearray()
    
    for cp, gbytes in glyphs_raw:
        chix_bytes.extend(struct.pack(">IBI", cp, 0, cur_offset))
        glyphs_body.extend(gbytes)
        cur_offset += len(gbytes)
        
    header.extend(b"CHIX" + struct.pack(">I", chix_len) + chix_bytes)
    header.extend(b"DATA\xff\xff\xff\xff" + glyphs_body)
    
    with open(out_path, "wb") as f:
        f.write(header)
    print(f"Created font: {out_path} ({len(header)} bytes, {num_chars} glyphs)")

