# Dimensions for a reference card slice:
def render_9slice(prefix, selected=False):
    S = 32
    # Colors
    if selected:
        bg_col = (14, 20, 32, 235)       # High opacity dark cyber glass
        border_col = (252, 238, 9, 255)   # Cyberpunk electric yellow
        glow_col = (252, 238, 9, 120)     # Golden yellow outer glow
        accent_col = (255, 0, 60, 255)    # Arasaka crimson warning notch
    else:
        bg_col = (8, 12, 20, 205)        # Dark translucent slate glass
        border_col = (0, 220, 255, 175)   # Faint electric cyan
        glow_col = (0, 220, 255, 50)      # Subtle cyan ambient glow
        accent_col = (0, 240, 255, 220)   # Cyan tech bracket

    # Full test card of 128x128 to slice properly
    canvas = Image.new("RGBA", (128, 128), (0, 0, 0, 0))
    d = ImageDraw.Draw(canvas)
    
    # Outer glow (if selected)
    if selected:
        glow_layer = Image.new("RGBA", (128, 128), (0, 0, 0, 0))
        gd = ImageDraw.Draw(glow_layer)
        gd.rounded_rectangle([4, 4, 123, 123], radius=10, fill=None, outline=glow_col, width=4)
        glow_layer = glow_layer.filter(ImageFilter.GaussianBlur(radius=3))
        canvas.paste(glow_layer, (0, 0), glow_layer)

    # Base shape polygon with top-right 45° chamfer cut (Cyberpunk signature silhouette)
    # NW=(8,8), NE chamfer start=(104,8), NE chamfer end=(120,24), SE=(120,120), SW=(8,120)
    poly = [
        (8, 8),
        (104, 8),
        (120, 24),
        (120, 120),
        (8, 120)
    ]
    
    # Fill
    d.polygon(poly, fill=bg_col)
    
    # Border stroke
    b_width = 2 if selected else 1
    d.line([(8, 8), (104, 8), (120, 24), (120, 120), (8, 120), (8, 8)], fill=border_col, width=b_width)
    
    # Corner technical brackets & accents
    if selected:
        # Arasaka red chamfer flag on top right
        d.polygon([(102, 8), (120, 26), (116, 26), (102, 12)], fill=accent_col)
        # Top-left corner tech dot
        d.rectangle([12, 12, 15, 15], fill=border_col)
        # Bottom corner brackets
        d.line([(8, 110), (8, 120), (18, 120)], fill=border_col, width=2)
        d.line([(120, 110), (120, 120), (110, 120)], fill=border_col, width=2)
    else:
        # Subtle cyan tech notch on chamfer
        d.line([(106, 10), (118, 22)], fill=accent_col, width=2)
        # Top-left corner tick
        d.line([(8, 8), (8, 16)], fill=accent_col, width=1)
        d.line([(8, 8), (16, 8)], fill=accent_col, width=1)

    # Slice into 9 parts: NW, N, NE, W, C, E, SW, S, SE
    # Corner size 32x32, center 64x64
    slices = {
        f"{prefix}_nw.png": canvas.crop((0, 0, 32, 32)),
        f"{prefix}_n.png":  canvas.crop((32, 0, 96, 32)).resize((32, 32), Image.Resampling.LANCZOS),
        f"{prefix}_ne.png": canvas.crop((96, 0, 128, 32)),
        f"{prefix}_w.png":  canvas.crop((0, 32, 32, 96)).resize((32, 32), Image.Resampling.LANCZOS),
        f"{prefix}_c.png":  canvas.crop((48, 48, 80, 80)).resize((32, 32), Image.Resampling.LANCZOS),
        f"{prefix}_e.png":  canvas.crop((96, 32, 128, 96)).resize((32, 32), Image.Resampling.LANCZOS),
        f"{prefix}_sw.png": canvas.crop((0, 96, 32, 128)),
        f"{prefix}_s.png":  canvas.crop((32, 96, 96, 128)).resize((32, 32), Image.Resampling.LANCZOS),
        f"{prefix}_se.png": canvas.crop((96, 96, 128, 128)),
    }
    
    for filename, img in slices.items():
        p = os.path.join(THEME_DIR, filename)
        img.save(p, "PNG")
    print(f"Generated 9-slice tiles for {prefix}")

