# 64x64 resolution, 4x supersampled with glowing neon vector aesthetic
def make_icon(draw_func, name):
    sz = 256
    img = Image.new("RGBA", (sz, sz), (0, 0, 0, 0))
    glow = Image.new("RGBA", (sz, sz), (0, 0, 0, 0))
    core = Image.new("RGBA", (sz, sz), (0, 0, 0, 0))
    
    gd = ImageDraw.Draw(glow)
    cd = ImageDraw.Draw(core)
    
    draw_func(gd, cd, sz)
    
    # Filter glow
    glow = glow.filter(ImageFilter.GaussianBlur(radius=10))
    img = Image.alpha_composite(img, glow)
    img = Image.alpha_composite(img, core)
    
    out = img.resize((64, 64), Image.Resampling.LANCZOS)
    out_path = os.path.join(ICONS_DIR, f"{name}.png")
    out.save(out_path, "PNG")
    return out_path

